#include "system.hpp"
#include "util/constructors.hpp"
#include <vector>
#include <fstream>

using namespace Emulator;

// generated by an LLM
std::vector<Byte> loadProgram(const std::string& filepath) {
    // Open in binary mode and seek to the end to get the file size
    std::ifstream file(filepath, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open binary file: " + filepath);
    }

    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);

    std::vector<Byte> buffer(size);
    if (file.read(reinterpret_cast<char*>(buffer.data()), size)) {
        return buffer;
    }

    throw std::runtime_error("Failed to read binary file: " + filepath);
}

int main() {
    std::vector<std::shared_ptr<Device>> deviceList;
    std::shared_ptr<Display> display = Constructors::createPixelDisplayDevice(0x40, 48, 16, Display::RefreshRate::EIGHT);

    auto initData = loadProgram("program.bin");

    deviceList.push_back(display);
    // Zpg and stack
    deviceList.push_back(Constructors::createMemoryDevice(0x00, 0x2));
    // System interface
    deviceList.push_back(Constructors::createSystemInterfaceDevice(0x43));
    // Program ROM
    // rom starts at $8000, ends $FFFF (128 pages)
    deviceList.push_back(Constructors::createMemoryDevice(0x80, 0x80, true, initData));

    System sys(deviceList, display);
    sys.powerOn();
    sys.run(std::cout);

    std::cout << "Done\n";
}
